import { Component, ChangeDetectionStrategy, viewChild } from '@angular/core';
import { NavbarComponent } from './components/navbar/navbar.component';
import { HeroComponent } from './components/hero/hero.component';
import { ServicesGridComponent } from './components/services-grid/services-grid.component';
import { CampusesComponent } from './components/campuses/campuses.component';
import { FooterComponent } from './components/footer/footer.component';
import { AssistantComponent } from '../assistant/assistant.component';

@Component({
  selector: 'app-landing',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    NavbarComponent,
    HeroComponent,
    ServicesGridComponent,
    CampusesComponent,
    FooterComponent,
    AssistantComponent
  ],
  template: `
    <div class="min-h-screen flex flex-col bg-white">
      <app-navbar (openChat)="onOpenChat()" />
      <main class="flex-1">
        <app-hero 
          (openChat)="onOpenChat()" 
          (askPrompt)="handleAskPrompt($event)" 
        />
        <app-services-grid 
          (askPrompt)="handleAskPrompt($event)" 
        />
        <app-campuses 
          (askPrompt)="handleAskPrompt($event)" 
        />
      </main>
      <app-footer (openChat)="onOpenChat()" />
      <app-assistant #assistant />
    </div>
  `
})
export class LandingComponent {
  private readonly assistant = viewChild<AssistantComponent>('assistant');

  onOpenChat(): void {
    this.assistant()?.openChat();
  }

  handleAskPrompt(prompt: string): void {
    this.assistant()?.openWithPrompt(prompt);
  }
}
