import { Component, ChangeDetectionStrategy, inject, signal } from '@angular/core';
import { ChatMessage } from '../../core/models/chat.model';
import { AssistantService } from '../../core/services/assistant.service';
import { ChatBubbleComponent } from './components/chat-bubble/chat-bubble.component';
import { ChatHeaderComponent } from './components/chat-header/chat-header.component';
import { ChatMessagesComponent } from './components/chat-messages/chat-messages.component';
import { ChatSuggestionsComponent } from './components/chat-suggestions/chat-suggestions.component';
import { ChatInputComponent } from './components/chat-input/chat-input.component';

@Component({
  selector: 'app-assistant',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    ChatBubbleComponent,
    ChatHeaderComponent,
    ChatMessagesComponent,
    ChatSuggestionsComponent,
    ChatInputComponent
  ],
  template: `
    <!-- Botón Flotante -->
    <app-chat-bubble 
      [isOpen]="isOpen()" 
      (toggle)="toggleChat()" 
    />

    <!-- Ventana del Asistente Virtual -->
    @if (isOpen()) {
      <div 
        class="fixed bottom-24 right-4 sm:right-6 z-50 w-[calc(100vw-2rem)] sm:w-[420px] h-[580px] max-h-[calc(100vh-8rem)] bg-white rounded-3xl shadow-2xl border border-slate-200/90 flex flex-col overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-200">
        
        <!-- Cabecera -->
        <app-chat-header 
          class="shrink-0"
          (close)="closeChat()" 
          (resetConversation)="resetConversation()" 
        />

        <!-- Área de Mensajes con Scroll -->
        <app-chat-messages 
          class="flex-1 min-h-0 flex flex-col overflow-hidden"
          [messages]="messages()" 
          [isLoading]="isLoading()" 
        />

        <!-- Sugerencias Rápidas -->
        <app-chat-suggestions 
          class="shrink-0"
          (selectSuggestion)="sendMessage($event)" 
        />

        <!-- Input de Envío -->
        <app-chat-input 
          class="shrink-0"
          [disabled]="isLoading()" 
          (send)="sendMessage($event)" 
        />

      </div>
    }
  `
})
export class AssistantComponent {
  private readonly assistantService = inject(AssistantService);

  readonly isOpen = signal<boolean>(false);
  readonly isLoading = signal<boolean>(false);

  private readonly initialGreeting: ChatMessage = {
    id: 'welcome_1',
    sender: 'assistant',
    text: '¡Hola! Te doy la bienvenida al **Asistente Virtual del Colegio Bertolt Brecht**.\n\nPuedo orientarte con cualquier duda sobre **secretaría y trámites**, **pagos de pensiones**, **talleres y deportes**, **plataformas escolares** o el proceso de **matrícula 2026**.\n\n¿En qué te puedo ayudar hoy?',
    timestamp: new Date()
  };

  readonly messages = signal<ChatMessage[]>([this.initialGreeting]);

  toggleChat(): void {
    this.isOpen.update(v => !v);
  }

  openChat(): void {
    this.isOpen.set(true);
  }

  closeChat(): void {
    this.isOpen.set(false);
  }

  openWithPrompt(prompt: string): void {
    this.openChat();
    this.sendMessage(prompt);
  }

  sendMessage(text: string): void {
    if (!text.trim() || this.isLoading()) return;

    // 1. Agregar mensaje del usuario
    const userMsg: ChatMessage = {
      id: 'usr_' + Date.now(),
      sender: 'user',
      text: text.trim(),
      timestamp: new Date()
    };

    this.messages.update(msgs => [...msgs, userMsg]);
    this.isLoading.set(true);

    // 2. Llamar al servicio RAG
    this.assistantService.askQuestion(text).subscribe({
      next: (response) => {
        const assistantMsg: ChatMessage = {
          id: 'asst_' + Date.now(),
          sender: 'assistant',
          text: response.texto_generado,
          timestamp: new Date(),
          fuentes: response.fuentes
        };

        this.messages.update(msgs => [...msgs, assistantMsg]);
        this.isLoading.set(false);
      },
      error: (error) => {
        const errorMsg: ChatMessage = {
          id: 'err_' + Date.now(),
          sender: 'assistant',
          text: error.message || 'Lo sentimos, ocurrió un problema al conectar con el servidor. Por favor, reintenta en unos instantes.',
          timestamp: new Date(),
          isError: true
        };

        this.messages.update(msgs => [...msgs, errorMsg]);
        this.isLoading.set(false);
      }
    });
  }

  resetConversation(): void {
    this.assistantService.resetConversation();
    this.messages.set([
      {
        id: 'welcome_' + Date.now(),
        sender: 'assistant',
        text: 'He iniciado una nueva conversación. ¿En qué otro tema o servicio del colegio puedo colaborarte?',
        timestamp: new Date()
      }
    ]);
  }
}
