import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, catchError, map, throwError } from 'rxjs';
import { environment } from '../../../environments/environment';
import { RagRequest, RagResponse } from '../models/chat.model';
import { SessionService } from './session.service';

@Injectable({
  providedIn: 'root'
})
export class AssistantService {
  private readonly http = inject(HttpClient);
  private readonly sessionService = inject(SessionService);
  private readonly endpoint = `${environment.apiUrl}/rag`;

  askQuestion(pregunta: string): Observable<RagResponse> {
    const payload: RagRequest = {
      pregunta: pregunta.trim(),
      session_id: this.sessionService.getSessionId(),
      usuario_id: 'padre_familia_cbb'
    };

    return this.http.post<RagResponse>(this.endpoint, payload).pipe(
      map(response => response),
      catchError(error => {
        console.error('Error al conectar con el Asistente Virtual:', error);
        return throwError(() => new Error(
          error.status === 0
            ? 'No se pudo conectar con el servidor del asistente. Por favor, asegúrate de que el backend esté activo en http://localhost:8000.'
            : (error.error?.detail || error.error?.mensaje_respuesta || 'Ocurrió un error al procesar tu consulta.')
        ));
      })
    );
  }

  resetConversation(): void {
    this.sessionService.resetSession();
  }
}
