import { Pipe, PipeTransform, inject } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { marked } from 'marked';
import DOMPurify from 'dompurify';

@Pipe({
  name: 'markdown',
  standalone: true
})
export class MarkdownPipe implements PipeTransform {
  private readonly sanitizer = inject(DomSanitizer);

  constructor() {
    marked.setOptions({
      gfm: true,
      breaks: true
    });
  }

  transform(value: string | null | undefined): SafeHtml {
    if (!value) return '';

    // 1. Convertir markdown completo (listas anidadas, negritas, cursivas, etc.)
    const parsedHtml = marked.parse(value) as string;

    // 2. Sanitizar HTML contra XSS
    const cleanHtml = DOMPurify.sanitize(parsedHtml);

    // 3. Marcar como seguro para Angular
    return this.sanitizer.bypassSecurityTrustHtml(cleanHtml);
  }
}
